describe('Right-click Context Menu on Table Row', () => {
  beforeEach(() => {
    cy.visit('/table-list');
  });

  it('should display context menu with right-click on table row', () => {
    // Verify table is visible
    cy.get('[data-testid="table-container"]').should('be.visible');

    // Get the first row
    cy.get('[data-testid="table-row-1"]').should('be.visible');

    // Right-click on the row
    cy.get('[data-testid="table-row-1"]').trigger('contextmenu');

    // Verify context menu appears
    cy.get('[data-testid="context-menu"]').should('be.visible');

    // Verify menu items are present
    cy.get('[data-testid="context-menu-item-edit"]').should('be.visible');
    cy.get('[data-testid="context-menu-item-delete"]').should('be.visible');
    cy.get('[data-testid="context-menu-item-view"]').should('be.visible');

    // Verify menu is not visible when clicking elsewhere
    cy.get('[data-testid="table-row-2"]').click();
    cy.get('[data-testid="context-menu"]').should('not.exist');
  });

  it('should handle right-click on disabled row and show disabled message', () => {
    // Verify table is visible
    cy.get('[data-testid="table-container"]').should('be.visible');

    // Get a disabled row
    cy.get('[data-testid="table-row-disabled"]').should('be.visible');

    // Right-click on the disabled row
    cy.get('[data-testid="table-row-disabled"]').trigger('contextmenu');

    // Verify context menu appears
    cy.get('[data-testid="context-menu"]').should('be.visible');

    // Verify disabled message is displayed
    cy.get('[data-testid="context-menu-item-edit"]').should('be.visible');
    cy.get('[data-testid="context-menu-item-delete"]').should('be.visible');
    cy.get('[data-testid="context-menu-item-view"]').should('be.visible');

    // Verify disabled message is present
    cy.get('[data-testid="context-menu-disabled-message"]').should('be.visible');
    cy.get('[data-testid="context-menu-disabled-message"]').should('contain', 'Row is disabled');

    // Verify menu items are not clickable
    cy.get('[data-testid="context-menu-item-edit"]').should('be.visible');
    cy.get('[data-testid="context-menu-item-edit"]').should('not.be.clickable');
    cy.get('[data-testid="context-menu-item-delete"]').should('not.be.clickable');
    cy.get('[data-testid="context-menu-item-view"]').should('not.be.clickable');
  });
});
